/**
 * Vanilla JavaScript Example - Using CoolProp WASM in any JavaScript application
 * 
 * This example shows how to use CoolProp in vanilla JavaScript, Node.js, or any framework.
 */

import { PropsSI, createAbstractState, getCoolProp, createMixture } from 'coolprop-wasm/simple';

// Example 1: Basic property calculations
async function basicExample() {
    console.log('=== Basic Property Calculations ===');
    
    try {
        // Calculate water properties at different conditions
        const density = await PropsSI('D', 'T', 300, 'P', 101325, 'Water');
        console.log(`Water density at 300K, 1 atm: ${density.toFixed(2)} kg/m³`);
        
        const enthalpy = await PropsSI('H', 'T', 373.15, 'Q', 0, 'Water');
        console.log(`Water enthalpy at saturation (100°C): ${(enthalpy/1000).toFixed(1)} kJ/kg`);
        
        const temperature = await PropsSI('T', 'P', 101325, 'Q', 0, 'Water');
        console.log(`Water saturation temperature at 1 atm: ${(temperature-273.15).toFixed(2)} °C`);
        
    } catch (error) {
        console.error('Error in basic example:', error.message);
    }
}

// Example 2: Using AbstractState for advanced calculations
async function abstractStateExample() {
    console.log('\n=== AbstractState Advanced Calculations ===');
    
    try {
        // Create AbstractState for water
        const state = await createAbstractState('HEOS', 'Water');
        const coolprop = await getCoolProp();
        
        // Update to 300K, 1 atm
        state.update(coolprop.input_pairs.PT_INPUTS, 101325, 300);
        
        // Get multiple properties
        console.log('Water properties at 300K, 1 atm:');
        console.log(`  Temperature: ${state.T().toFixed(2)} K`);
        console.log(`  Pressure: ${(state.p()/1000).toFixed(1)} kPa`);
        console.log(`  Density: ${state.rhomass().toFixed(2)} kg/m³`);
        console.log(`  Enthalpy: ${(state.hmass()/1000).toFixed(1)} kJ/kg`);
        console.log(`  Entropy: ${(state.smass()/1000).toFixed(3)} kJ/kg/K`);
        
        // Calculate derivatives
        const dP_dT = state.first_partial_deriv(
            coolprop.parameters.iP,
            coolprop.parameters.iT,
            coolprop.parameters.iDmolar
        );
        console.log(`  dP/dT|ρ: ${dP_dT.toFixed(0)} Pa/K`);
        
        // Update to different state
        state.update(coolprop.input_pairs.QT_INPUTS, 0, 373.15); // Saturated liquid at 100°C
        console.log('\nSaturated water at 100°C:');
        console.log(`  Pressure: ${(state.p()/1000).toFixed(1)} kPa`);
        console.log(`  Density: ${state.rhomass().toFixed(1)} kg/m³`);
        
    } catch (error) {
        console.error('Error in AbstractState example:', error.message);
    }
}

// Example 3: Working with different fluids
async function multiFluidExample() {
    console.log('\n=== Multi-Fluid Calculations ===');
    
    const fluids = ['Water', 'CO2', 'Nitrogen', 'Oxygen'];
    const temperature = 300; // K
    const pressure = 101325; // Pa
    
    console.log(`Properties at ${temperature}K, ${pressure/1000}kPa:`);
    
    for (const fluid of fluids) {
        try {
            const density = await PropsSI('D', 'T', temperature, 'P', pressure, fluid);
            const viscosity = await PropsSI('V', 'T', temperature, 'P', pressure, fluid);
            
            console.log(`  ${fluid}:`);
            console.log(`    Density: ${density.toFixed(3)} kg/m³`);
            console.log(`    Viscosity: ${(viscosity*1e6).toFixed(2)} μPa·s`);
            
        } catch (error) {
            console.log(`    ${fluid}: Error - ${error.message}`);
        }
    }
}

// Example 4: Mixture calculations
async function mixtureExample() {
    console.log('\n=== Mixture Calculations ===');
    
    try {
        // Create air mixture (simplified: 78% N2, 22% O2)
        const air = await createMixture(['Nitrogen', 'Oxygen'], [0.78, 0.22]);
        const coolprop = await getCoolProp();
        
        // Update to standard conditions
        air.update(coolprop.input_pairs.PT_INPUTS, 101325, 298.15);
        
        console.log('Air mixture (78% N2, 22% O2) at 25°C, 1 atm:');
        console.log(`  Density: ${air.rhomass().toFixed(3)} kg/m³`);
        console.log(`  Molar mass: ${(air.molar_mass()*1000).toFixed(2)} g/mol`);
        
    } catch (error) {
        console.error('Error in mixture example:', error.message);
    }
}

// Example 5: Error handling
async function errorHandlingExample() {
    console.log('\n=== Error Handling ===');
    
    try {
        // This should fail - invalid fluid
        await PropsSI('D', 'T', 300, 'P', 101325, 'InvalidFluid');
    } catch (error) {
        console.log('Expected error for invalid fluid:', error.message);
    }
    
    try {
        // This should fail - invalid property
        await PropsSI('InvalidProperty', 'T', 300, 'P', 101325, 'Water');
    } catch (error) {
        console.log('Expected error for invalid property:', error.message);
    }
    
    try {
        // This should fail - invalid state point
        await PropsSI('D', 'T', -100, 'P', 101325, 'Water'); // Below triple point
    } catch (error) {
        console.log('Expected error for invalid state:', error.message);
    }
}

// Run all examples
async function runAllExamples() {
    console.log('CoolProp WASM Vanilla JavaScript Examples\n');
    
    await basicExample();
    await abstractStateExample();
    await multiFluidExample();
    await mixtureExample();
    await errorHandlingExample();
    
    console.log('\n=== All examples completed ===');
}

// Export for use in other modules
export {
    basicExample,
    abstractStateExample,
    multiFluidExample,
    mixtureExample,
    errorHandlingExample,
    runAllExamples
};

// Run examples if this file is executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
    runAllExamples().catch(console.error);
}